53:   const [isSavesModalOpen, setIsSavesModalOpen] = useState<boolean>(false);
54:   const [slots, setSlots] = useState<SaveSlot[]>([]);
55:   const [lastAutoSaveTime, setLastAutoSaveTime] = useState<number | null>(getLastAutoSaveTime());
56:   const [saveToast, setSaveToast] = useState<{ message: string; time: string } | null>(null);
