82:   // Trigger autosave on meaningful state updates
83:   const triggerAutoSave = (newSeason: SeasonState, newPlayers: Player[]) => {
84:     autoSaveCurrentState(newSeason, newPlayers);
85:     const now = Date.now();
86:     setLastAutoSaveTime(now);
87:     showSaveToast('Матч завершен и сохранен');
88:     reloadSlots();
89:   };
90: 
91:   const currentTournament = season.tournaments[season.currentTournamentIndex] || season.tournaments[0];
92: 
93:   // Match finished in interactive MatchViewer
94:   const handleMatchFinishedFromViewer = (matchId: string, winnerId: string, score: MatchScore) => {
95:     const updatedTournaments = [...season.tournaments];
96:     const currTourn = updatedTournaments[season.currentTournamentIndex];
97:     const targetMatch = currTourn.matches.find((m) => m.id === matchId);
98:     if (targetMatch) {
99:       targetMatch.score = score;
100:     }
101: 
102:     const { updatedTournament, updatedPlayers } = advanceTournamentMatch(
103:       currTourn,
104:       matchId,
105:       winnerId,
106:       players
107:     );
108: 
109:     let finalPlayers = updatedPlayers;
110:     if (updatedTournament.isCompleted) {
111:       finalPlayers = finalizeTournamentAndDistributePoints(updatedTournament, updatedPlayers);
112:     }
113: 
114:     updatedTournaments[season.currentTournamentIndex] = updatedTournament;
115:     const newSeasonState: SeasonState = {
116:       ...season,
117:       tournaments: updatedTournaments,
118:     };
119: 
120:     setSeason(newSeasonState);
121:     setPlayers(finalPlayers);
122:     triggerAutoSave(newSeasonState, finalPlayers);
123:   };
124: 
125:   // Instant simulate 1 single match
126:   const handleSimulateSingleMatch = (match: Match) => {
127:     if (!match.player1Id || !match.player2Id) return;
128:     const p1 = players.find((p) => p.id === match.player1Id);
129:     const p2 = players.find((p) => p.id === match.player2Id);
130:     if (!p1 || !p2) return;
131: 
132:     const sim = simulateFullMatch(p1, p2, currentTournament.surface, currentTournament.setsToWin);
133:     const updatedTournaments = [...season.tournaments];
134:     const currTourn = updatedTournaments[season.currentTournamentIndex];
135:     const targetMatch = currTourn.matches.find((m) => m.id === match.id);
136:     if (targetMatch) {
137:       targetMatch.score = sim.score;
138:     }
139: 
140:     const { updatedTournament, updatedPlayers } = advanceTournamentMatch(
141:       currTourn,
142:       match.id,
143:       sim.winnerId,
144:       players
145:     );
146: 
147:     let finalPlayers = updatedPlayers;
148:     if (updatedTournament.isCompleted) {
149:       finalPlayers = finalizeTournamentAndDistributePoints(updatedTournament, updatedPlayers);
150:     }
151: 
152:     updatedTournaments[season.currentTournamentIndex] = updatedTournament;
153:     const newSeason: SeasonState = {
154:       ...season,
155:       tournaments: updatedTournaments,
156:     };
157: 
158:     setSeason(newSeason);
159:     setPlayers(finalPlayers);
160:     triggerAutoSave(newSeason, finalPlayers);
161:   };
162: 
163:   // Simulate current unplayed round of tournament
164:   const handleSimulateCurrentRound = () => {
165:     let currTourn = { ...currentTournament };
166:     let currPlayers = [...players];
167:     const updatedTournaments = [...season.tournaments];
168: 
169:     // Find the lowest round with uncompleted matches
170:     const uncompleted = currTourn.matches.filter((m) => !m.isCompleted);
171:     if (uncompleted.length === 0) return;
172: 
173:     const roundToSimulate = Math.min(...uncompleted.map((m) => m.round));
174:     const roundMatches = currTourn.matches.filter((m) => m.round === roundToSimulate && !m.isCompleted);
175: 
176:     for (const m of roundMatches) {
177:       if (m.player1Id && m.player2Id) {
178:         const p1 = currPlayers.find((p) => p.id === m.player1Id);
179:         const p2 = currPlayers.find((p) => p.id === m.player2Id);
180:         if (p1 && p2) {
181:           const sim = simulateFullMatch(p1, p2, currTourn.surface, currTourn.setsToWin);
182:           m.score = sim.score;
183:           const adv = advanceTournamentMatch(currTourn, m.id, sim.winnerId, currPlayers);
184:           currTourn = adv.updatedTournament;
185:           currPlayers = adv.updatedPlayers;
186:         }
187:       }
188:     }
189: 
190:     if (currTourn.isCompleted) {
191:       currPlayers = finalizeTournamentAndDistributePoints(currTourn, currPlayers);
192:     }
193: 
194:     updatedTournaments[season.currentTournamentIndex] = currTourn;
195:     const newSeason: SeasonState = {
196:       ...season,
197:       tournaments: updatedTournaments,
198:     };
199: 
200:     setSeason(newSeason);
201:     setPlayers(currPlayers);
202:     triggerAutoSave(newSeason, currPlayers);
203:   };
204: 
205:   // Simulate entire current tournament
206:   const handleSimulateEntireTournament = () => {
207:     const { completedTournament, updatedPlayers } = simulateEntireTournament(
208:       currentTournament,
209:       players
210:     );
211: 
212:     const updatedTournaments = [...season.tournaments];
213:     updatedTournaments[season.currentTournamentIndex] = completedTournament;
214: 
215:     const newSeason: SeasonState = {
216:       ...season,
217:       tournaments: updatedTournaments,
218:     };
219: 
220:     setSeason(newSeason);
221:     setPlayers(updatedPlayers);
222:     triggerAutoSave(newSeason, updatedPlayers);
223:   };
224: 
225:   // Next tournament in calendar
226:   const handleNextTournament = () => {
227:     const nextIdx = season.currentTournamentIndex + 1;
228:     if (nextIdx < season.tournaments.length) {
229:       setSeason({
230:         ...season,
231:         currentTournamentIndex: nextIdx,
232:       });
233:       setCurrentTab('tournament');
234:       window.scrollTo({ top: 0, behavior: 'smooth' });
235:     } else {
236:       // Season completed! Show Year-End transition modal
237:       const atpNo1 = players.find((p) => p.tour === 'ATP' && p.rank === 1) || null;
238:       const wtaNo1 = players.find((p) => p.tour === 'WTA' && p.rank === 1) || null;
239: 
240:       setTransitionReport({
241:         year: season.year,
242:         nextYear: season.year + 1,
243:         atpChampion: atpNo1,
244:         wtaChampion: wtaNo1,
245:       });
246:     }
247:   };
248: 
249:   // Advance to next season year
250:   const handleStartNextSeasonYear = () => {
251:     if (!transitionReport) return;
252:     const nextYear = transitionReport.nextYear;
253:     setTransitionReport(null);
254: 
255:     // Evolve players: age + 1, slight rating growth or decline
256:     const evolvedPlayers = players.map((p) => {
257:       const isYoung = p.age < 23;
258:       const isVeteran = p.age > 33;
259:       const delta = isYoung ? 1 : isVeteran ? -1 : 0;
260: 
261:       return {
262:         ...p,
263:         age: p.age + 1,
264:         stats: {
265:           ...p.stats,
266:           serve: Math.min(99, Math.max(50, p.stats.serve + delta)),
267:           forehand: Math.min(99, Math.max(50, p.stats.forehand + delta)),
268:           backhand: Math.min(99, Math.max(50, p.stats.backhand + delta)),
269:           speed: Math.min(99, Math.max(50, p.stats.speed + (isVeteran ? -2 : delta))),
270:         },
271:       };
272:     });
273: 
274:     const newSeason = initializeNewSeason(evolvedPlayers, nextYear);
275:     setSeason(newSeason);
276:     setPlayers(evolvedPlayers);
277:     triggerAutoSave(newSeason, evolvedPlayers);
278:     setCurrentTab('tournament');
279:   };
280: 
281:   // Save Slots handlers
282:   const handleSaveToSlot = (slotId: number) => {
283:     saveToSlot(slotId, `Турнир: ${currentTournament.nameRu}`, season, players);
284:     reloadSlots();
285:     showSaveToast(`Сохранено в Слот #${slotId}`);
286:   };
287: 
288:   const handleLoadFromSlot = (slotId: number) => {
289:     const loaded = loadFromSlot(slotId);
290:     if (loaded) {
291:       const repaired = repairSeasonState(loaded.season, loaded.players);
292:       setSeason(repaired);
293:       setPlayers(loaded.players);
294:       setIsSavesModalOpen(false);
295:       showSaveToast(`Загружен Слот #${slotId}`);
296:     }
297:   };
298: 
299:   const handleDeleteSlot = (slotId: number) => {
300:     deleteSlot(slotId);
301:     reloadSlots();
302:   };
303: 
304:   const handleImportSave = (impSeason: SeasonState, impPlayers: Player[]) => {
305:     const repaired = repairSeasonState(impSeason, impPlayers);
306:     setSeason(repaired);
307:     setPlayers(impPlayers);
308:     triggerAutoSave(repaired, impPlayers);
309:     showSaveToast('Сохранение успешно импортировано');
310:   };
311: 
312:   const handleResetSeason = () => {
313:     const initialP = getInitialPlayers();
314:     const newS = initializeNewSeason(initialP, 2026);
315:     setPlayers(initialP);
316:     setSeason(newS);
317:     triggerAutoSave(newS, initialP);
318:     showSaveToast('Сезон сброшен к началу 2026 года');
319:   };
320: 
321:   return (
322:     <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col selection:bg-emerald-500 selection:text-slate-950 font-sans">
323:       {/* Global Top Navbar */}
324:       <Navbar
325:         currentTab={currentTab}
326:         onTabChange={(tab) => {
327:           setCurrentTab(tab);
328:           if (tab !== 'match') setActiveMatchToWatch(null);
329:         }}
330:         year={season.year}
331:         currentTournament={currentTournament}
332:         onOpenSaves={() => setIsSavesModalOpen(true)}
333:         lastAutoSaveTime={lastAutoSaveTime}
334:       />
335: 
336:       {/* Main Container View Area */}
337:       <main className="flex-1 max-w-7xl w-full mx-auto px-3 sm:px-6 lg:px-8 pt-6">
338:         {currentTab === 'tournament' && (
339:           <TournamentBracket
340:             tournament={currentTournament}
341:             players={players}
342:             onSelectMatchToWatch={(match) => {
343:               setActiveMatchToWatch(match);
344:               setCurrentTab('match');
345:             }}
346:             onSimulateMatch={handleSimulateSingleMatch}
347:             onSimulateCurrentRound={handleSimulateCurrentRound}
348:             onSimulateEntireTournament={handleSimulateEntireTournament}
349:             onNextTournament={handleNextTournament}
350:           />
351:         )}
352: 
353:         {currentTab === 'match' && (
354:           <div>
355:             {activeMatchToWatch && activeMatchToWatch.player1Id && activeMatchToWatch.player2Id ? (
356:               <MatchViewer
357:                 match={activeMatchToWatch}
358:                 player1={players.find((p) => p.id === activeMatchToWatch.player1Id)!}
359:                 player2={players.find((p) => p.id === activeMatchToWatch.player2Id)!}
360:                 surface={currentTournament.surface}
361:                 setsToWin={currentTournament.setsToWin}
362:                 onMatchFinished={handleMatchFinishedFromViewer}
363:                 onBackToBracket={() => setCurrentTab('tournament')}
364:               />
365:             ) : (
366:               <div className="text-center py-16 bg-slate-900/60 border border-slate-800 rounded-3xl p-8 max-w-lg mx-auto">
367:                 <div className="text-4xl mb-3">🎾</div>
368:                 <h3 className="text-lg font-bold text-white mb-2">Матч не выбран</h3>
369:                 <p className="text-xs text-slate-400 mb-6">
370:                   Перейдите во вкладку «Сетка» и нажмите кнопку «Зритель» на любом доступном матче для просмотра в режиме реального времени.
371:                 </p>
372:                 <button
373:                   onClick={() => setCurrentTab('tournament')}
374:                   className="px-5 py-2.5 rounded-xl bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-bold text-xs transition cursor-pointer"
375:                 >
376:                   Перейти к сетке турнира
377:                 </button>
378:               </div>
379:             )}
380:           </div>
381:         )}
382: 
383:         {currentTab === 'rankings' && (
384:           <RankingsTable
385:             players={players}
386:             onSelectPlayer={(p) => setSelectedPlayerForModal(p)}
387:           />
388:         )}
389: 
390:         {currentTab === 'calendar' && (
391:           <CalendarView
392:             tournaments={season.tournaments}
393:             currentTournamentIndex={season.currentTournamentIndex}
394:             players={players}
395:             onSelectTournament={(idx) => {
396:               setSeason({ ...season, currentTournamentIndex: idx });
397:               setCurrentTab('tournament');
398:             }}
399:           />
400:         )}
401: 
402:         {currentTab === 'players' && (
403:           <PlayersDirectory
404:             players={players}
405:             onSelectPlayer={(p) => setSelectedPlayerForModal(p)}
406:           />
407:         )}
408:       </main>
409: 
410:       {/* Player Profile Detail Modal */}
411:       <PlayerProfileModal
412:         player={selectedPlayerForModal}
413:         onClose={() => setSelectedPlayerForModal(null)}
414:       />
415: 
416:       {/* Saves / Slots Modal */}
417:       <SavesModal
418:         isOpen={isSavesModalOpen}
419:         onClose={() => setIsSavesModalOpen(false)}
420:         currentSeason={season}
421:         currentPlayers={players}
422:         slots={slots}
423:         lastAutoSaveTime={lastAutoSaveTime}
424:         onSaveToSlot={handleSaveToSlot}
425:         onLoadFromSlot={handleLoadFromSlot}
426:         onDeleteSlot={handleDeleteSlot}
427:         onImportSave={handleImportSave}
428:         onResetSeason={handleResetSeason}
429:       />
430: 
431:       {/* Season Transition Modal */}
432:       <SeasonTransitionModal
433:         report={transitionReport}
434:         onClose={handleStartNextSeasonYear}
435:       />
436: 
437:       {/* Auto-save Toast notification */}
438:       {saveToast && (
439:         <div className="fixed bottom-5 right-5 z-50 flex items-center gap-2.5 px-4 py-2.5 rounded-2xl bg-slate-900 border border-emerald-500/40 text-white shadow-2xl backdrop-blur-md animate-fade-in">
440:           <span className="w-2 h-2 rounded-full bg-emerald-400 animate-ping" />
441:           <div className="text-xs">
442:             <span className="font-bold text-emerald-400">{saveToast.message}</span>
443:             <span className="text-slate-400 ml-1.5 font-mono text-[10px]">[{saveToast.time}]</span>
444:           </div>
445:         </div>
446:       )}
447: 
448:       {/* Offline Connectivity Status Indicator Banner */}
449:       <OfflineIndicator />
450:     </div>
451:   );
452: }
453: 
454: export default App;

