40: export function generateTournamentDraw(
41:   template: Omit<Tournament, 'matches' | 'isCompleted' | 'currentRound' | 'championId' | 'runnerUpId'>,
42:   allPlayers: Player[],
43:   _isFirst: boolean = false
44: ): Tournament {
45:   const eligiblePlayers = allPlayers
46:     .filter((p) => p.tour === template.tour && !p.retired)
47:     .sort((a, b) => a.rank - b.rank);
48: 
49:   const drawSize = template.drawSize;
50:   const numRounds = Math.log2(drawSize);
51: 
52:   // Take top ranked players up to drawSize
53:   const tournamentPlayers = eligiblePlayers.slice(0, drawSize);
54: 
55:   // Standard Tennis Seeding Placement (Seed 1 at top, Seed 2 at bottom, Seeds 3-4 in opposite halves)
56:   const seededIndices = getStandardBracketSeeding(drawSize);
57:   const seededDraw: Player[] = new Array(drawSize);
58: 
59:   for (let slot = 0; slot < drawSize; slot++) {
60:     const playerIdx = seededIndices[slot];
61:     seededDraw[slot] = tournamentPlayers[playerIdx] || tournamentPlayers[slot % tournamentPlayers.length];
62:   }
63: 
64:   // Generate matches round by round
65:   let currentRoundSize = drawSize / 2;
66:   const roundMatchesMap: Map<number, Match[]> = new Map();
67: 
68:   for (let round = 0; round < numRounds; round++) {
69:     const roundMatches: Match[] = [];
70:     const isFirstRound = round === 0;
71:     const roundName = getRoundName(round, numRounds);
72: 
73:     for (let m = 0; m < currentRoundSize; m++) {
74:       const matchId = `${template.id}-r${round}-m${m}`;
75: 
76:       let p1Id: string | null = null;
77:       let p2Id: string | null = null;
78:       let s1: number | undefined = undefined;
79:       let s2: number | undefined = undefined;
80: 
81:       if (isFirstRound) {
82:         const p1 = seededDraw[m * 2];
83:         const p2 = seededDraw[m * 2 + 1];
84:         p1Id = p1 ? p1.id : null;
85:         p2Id = p2 ? p2.id : null;
86:         if (p1 && p1.rank <= 32) s1 = p1.rank;
87:         if (p2 && p2.rank <= 32) s2 = p2.rank;
88:       }
89: 
90:       const match: Match = {
91:         id: matchId,
92:         tournamentId: template.id,
93:         round,
94:         roundName,
95:         player1Id: p1Id,
96:         player2Id: p2Id,
97:         seed1: s1,
98:         seed2: s2,
99:         isCompleted: false,
100:       };
101: 
102:       roundMatches.push(match);
103:     }
104: 
105:     roundMatchesMap.set(round, roundMatches);
106:     currentRoundSize /= 2;
107:   }
108: 
109:   // Link child matches to next match IDs
110:   for (let round = 0; round < numRounds - 1; round++) {
111:     const currMatches = roundMatchesMap.get(round)!;
112:     const nextMatches = roundMatchesMap.get(round + 1)!;
113: 
114:     for (let i = 0; i < currMatches.length; i++) {
115:       const targetNextMatch = nextMatches[Math.floor(i / 2)];
116:       currMatches[i].nextMatchId = targetNextMatch.id;
117:       currMatches[i].nextMatchSlot = (i % 2 === 0 ? 1 : 2);
118:     }
119:   }
120: 
121:   const allMatchesList: Match[] = [];
122:   for (let r = 0; r < numRounds; r++) {
123:     allMatchesList.push(...roundMatchesMap.get(r)!);
124:   }
125: 
126:   return {
127:     ...template,
128:     matches: allMatchesList,
129:     isCompleted: false,
130:     currentRound: 0,
131:   };
132: }
