19: export function getStandardBracketSeeding(drawSize: number): number[] {
20:   const rounds = Math.log2(drawSize);
21:   let list = [1, 2];
22:   for (let r = 1; r < rounds; r++) {
23:     const nextList: number[] = [];
24:     const sum = Math.pow(2, r + 1) + 1;
25:     for (let i = 0; i < list.length; i++) {
26:       if (i % 2 === 0) {
27:         nextList.push(list[i]);
28:         nextList.push(sum - list[i]);
29:       } else {
30:         nextList.push(sum - list[i]);
31:         nextList.push(list[i]);
32:       }
33:     }
34:     list = nextList;
35:   }
36:   // Convert 1-based seed numbers (1..N) to 0-based indices (0..N-1)
37:   return list.map((seed) => seed - 1);
38: }
