248: export function advanceTournamentMatch(
249:   tournament: Tournament,
250:   matchId: string,
251:   winnerId: string,
252:   players: Player[]
253: ): { updatedTournament: Tournament; updatedPlayers: Player[] } {
254:   const updatedTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
255:   const match = updatedTournament.matches.find((m) => m.id === matchId);
256:   if (!match) return { updatedTournament, updatedPlayers: players };
257: 
258:   match.isCompleted = true;
259:   match.winnerId = winnerId;
260: 
261:   // Propagate to next match
262:   if (match.nextMatchId) {
263:     const nextMatch = updatedTournament.matches.find((m) => m.id === match.nextMatchId);
264:     if (nextMatch) {
265:       if (match.nextMatchSlot === 1) {
266:         nextMatch.player1Id = winnerId;
267:         const winnerObj = players.find((p) => p.id === winnerId);
268:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed1 = winnerObj.rank;
269:       } else {
270:         nextMatch.player2Id = winnerId;
271:         const winnerObj = players.find((p) => p.id === winnerId);
272:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed2 = winnerObj.rank;
273:       }
274:     }
275:   }
276: 
277:   // Check if final match
278:   const maxRound = Math.log2(updatedTournament.drawSize) - 1;
279:   if (match.round === maxRound) {
280:     updatedTournament.isCompleted = true;
281:     updatedTournament.championId = winnerId;
282:     const loserId = match.player1Id === winnerId ? match.player2Id : match.player1Id;
283:     if (loserId) updatedTournament.runnerUpId = loserId;
284:   }
285: 
286:   // Update player form / match records
287:   const updatedPlayers = players.map((p) => {
288:     if (p.id === winnerId) {
289:       return {
290:         ...p,
291:         matchesWon: p.matchesWon + 1,
292:         form: Math.min(1.25, p.form + 0.01),
293:       };
294:     }
295:     const loserId = match.player1Id === winnerId ? match.player2Id : match.player1Id;
296:     if (p.id === loserId) {
297:       return {
298:         ...p,
299:         matchesLost: p.matchesLost + 1,
300:         form: Math.max(0.75, p.form - 0.015),
301:       };
302:     }
303:     return p;
304:   });
305: 
306:   return { updatedTournament, updatedPlayers };
307: }
