309: export function finalizeTournamentAndDistributePoints(
310:   tournament: Tournament,
311:   players: Player[]
312: ): Player[] {
313:   const pointsMap = new Map<string, { points: number; prize: number; wonTitle: boolean }>();
314: 
315:   tournament.matches.forEach((m) => {
316:     if (m.isCompleted && m.player1Id && m.player2Id) {
317:       const loserId = m.winnerId === m.player1Id ? m.player2Id : m.player1Id;
318:       const isWinner = m.winnerId;
319: 
320:       let roundPoints = 0;
321:       let roundPrize = 0;
322: 
323:       if (m.roundName === 'Финал') {
324:         if (isWinner) {
325:           pointsMap.set(isWinner, {
326:             points: tournament.pointsWinner,
327:             prize: Math.round(tournament.prizeMoneyPool * 0.22),
328:             wonTitle: true,
329:           });
330:         }
331:         if (loserId) {
332:           pointsMap.set(loserId, {
333:             points: tournament.pointsFinalist,
334:             prize: Math.round(tournament.prizeMoneyPool * 0.12),
335:             wonTitle: false,
336:           });
337:         }
338:       } else if (m.roundName === '1/2 финала' && loserId && !pointsMap.has(loserId)) {
339:         roundPoints = tournament.pointsSemi;
340:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.06);
341:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
342:       } else if (m.roundName === '1/4 финала' && loserId && !pointsMap.has(loserId)) {
343:         roundPoints = tournament.pointsQuarter;
344:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.035);
345:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
346:       } else if (m.roundName === '1/8 финала' && loserId && !pointsMap.has(loserId)) {
347:         roundPoints = tournament.pointsR16;
348:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.018);
349:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
350:       } else if (m.roundName === '1/16 финала' && loserId && !pointsMap.has(loserId)) {
351:         roundPoints = tournament.pointsR32;
352:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.009);
353:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
354:       } else if (m.roundName === '1/32 финала' && loserId && !pointsMap.has(loserId)) {
355:         roundPoints = tournament.pointsR64;
356:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.004);
357:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
358:       }
359:     }
360:   });
361: 
362:   const updatedPlayers = players.map((p) => {
363:     if (p.tour !== tournament.tour) return p;
364: 
365:     const tourneyPointsHistory = p.tournamentPoints || {};
366:     // Defended points = points earned at this specific tournament in the previous season edition
367:     const defendedPoints = tourneyPointsHistory[tournament.id] || 0;
368: 
369:     let earnedPoints = 0;
370:     let prize = 0;
371:     let wonTitle = false;
372: 
373:     if (pointsMap.has(p.id)) {
374:       const award = pointsMap.get(p.id)!;
375:       earnedPoints = award.points;
376:       prize = award.prize;
377:       wonTitle = award.wonTitle;
378:     } else {
379:       const playedInTournament = tournament.matches.some(
380:         (m) => m.player1Id === p.id || m.player2Id === p.id
381:       );
382:       if (playedInTournament) {
383:         earnedPoints = tournament.pointsR128 || tournament.pointsR64 || 0;
384:       }
385:     }
386: 
387:     const updatedTourneyPoints = {
388:       ...tourneyPointsHistory,
389:       [tournament.id]: earnedPoints,
390:     };
391: 
392:     const netPointsChange = earnedPoints - defendedPoints;
393:     const newPoints = Math.max(0, p.points + netPointsChange);
394: 
395:     return {
396:       ...p,
397:       previousPoints: p.points,
398:       points: newPoints,
399:       tournamentPoints: updatedTourneyPoints,
400:       prizeMoney: p.prizeMoney + prize,
401:       titles: wonTitle ? p.titles + 1 : p.titles,
402:       careerTitles: wonTitle ? p.careerTitles + 1 : p.careerTitles,
403:       grandSlams: wonTitle && tournament.category === 'Grand Slam' ? p.grandSlams + 1 : p.grandSlams,
404:     };
405:   });
406: 
407:   return recalculateRankings(updatedPlayers);
408: }
