410: export function recalculateRankings(players: Player[]): Player[] {
411:   const atp = players.filter((p) => p.tour === 'ATP' && !p.retired);
412:   const wta = players.filter((p) => p.tour === 'WTA' && !p.retired);
413:   const retired = players.filter((p) => p.retired);
414: 
415:   const sortTour = (list: Player[]) => {
416:     list.sort((a, b) => b.points - a.points || a.rank - b.rank);
417:     return list.map((p, idx) => ({
418:       ...p,
419:       previousRank: p.rank,
420:       rank: idx + 1,
421:     }));
422:   };
423: 
424:   const rankedAtp = sortTour(atp);
425:   const rankedWta = sortTour(wta);
426: 
427:   return [...rankedAtp, ...rankedWta, ...retired];
428: }
