430: export function simulateEntireTournament(
431:   tournament: Tournament,
432:   players: Player[]
433: ): { completedTournament: Tournament; updatedPlayers: Player[] } {
434:   let currTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
435:   let currPlayers = [...players];
436: 
437:   const totalRounds = Math.log2(currTournament.drawSize);
438: 
439:   for (let r = 0; r < totalRounds; r++) {
440:     const roundMatches = currTournament.matches.filter((m) => m.round === r && !m.isCompleted);
441:     for (const match of roundMatches) {
442:       if (match.player1Id && match.player2Id) {
443:         const p1 = currPlayers.find((p) => p.id === match.player1Id);
444:         const p2 = currPlayers.find((p) => p.id === match.player2Id);
445: 
446:         if (p1 && p2) {
447:           const sim = simulateFullMatch(p1, p2, currTournament.surface, currTournament.setsToWin);
448:           match.score = sim.score;
449:           const adv = advanceTournamentMatch(currTournament, match.id, sim.winnerId, currPlayers);
450:           currTournament = adv.updatedTournament;
451:           currPlayers = adv.updatedPlayers;
452:         }
453:       }
454:     }
455:   }
456: 
457:   currPlayers = finalizeTournamentAndDistributePoints(currTournament, currPlayers);
458:   return { completedTournament: currTournament, updatedPlayers: currPlayers };
459: }

