15: export function calculateSurfaceRating(player: Player, surface: SurfaceType): number {
16:   let affinity = 1.0;
17:   if (surface === 'Hard' || surface === 'Indoor Hard') {
18:     affinity = player.stats.hardAffinity;
19:   } else if (surface === 'Clay') {
20:     affinity = player.stats.clayAffinity;
21:   } else if (surface === 'Grass') {
22:     affinity = player.stats.grassAffinity;
23:   }
24: 
25:   const baseAverage = (
26:     player.stats.serve * 0.25 +
27:     player.stats.forehand * 0.25 +
28:     player.stats.backhand * 0.20 +
29:     player.stats.speed * 0.15 +
30:     player.stats.mental * 0.15
31:   );
32: 
33:   return baseAverage * affinity * (player.form || 1.0);
34: }
