36: export function simulateSinglePoint(
37:   player1: Player,
38:   player2: Player,
39:   surface: SurfaceType,
40:   server: 1 | 2,
41:   inTiebreak: boolean,
42:   currentScoreP1: number,
43:   currentScoreP2: number
44: ): PointSimulationResult {
45:   const servingPlayer = server === 1 ? player1 : player2;
46:   const receivingPlayer = server === 1 ? player2 : player1;
47: 
48:   const serverEffRating = calculateSurfaceRating(servingPlayer, surface);
49:   const receiverEffRating = calculateSurfaceRating(receivingPlayer, surface);
50: 
51:   // Pressure situation (break points, game points, tiebreak)
52:   const isPressure = inTiebreak || (currentScoreP1 >= 3 && currentScoreP2 >= 3);
53:   const serverClutch = isPressure ? (servingPlayer.stats.clutch / 100) : 1.0;
54:   const receiverClutch = isPressure ? (receivingPlayer.stats.clutch / 100) : 1.0;
55: 
56:   // Serve power & Ace probability
57:   const surfaceSpeed = surface === 'Grass' ? 1.25 : surface === 'Indoor Hard' ? 1.15 : surface === 'Hard' ? 1.05 : 0.85;
58:   const aceChance = ((servingPlayer.stats.serve - 60) / 300) * surfaceSpeed * 0.45;
59:   const dfChance = Math.max(0.015, (100 - servingPlayer.stats.mental) / 2000);
60: 
61:   const roll = Math.random();
62: 
63:   // 1. Double Fault
64:   if (roll < dfChance) {
65:     const pointWinner = server === 1 ? 2 : 1;
66:     return {
67:       winner: pointWinner,
68:       outcomeType: 'double_fault',
69:       rallyLength: 0,
70:       descriptionRu: `Двойная ошибка на подаче у ${servingPlayer.nameRu}`,
71:       ballPath: [{ x: 50, y: server === 1 ? 90 : 10 }, { x: 45, y: 50 }],
72:       isGameWon: false,
73:       isSetWon: false,
74:       isMatchWon: false,
75:       server,
76:     };
77:   }
78: 
79:   // 2. Ace
80:   if (roll < dfChance + aceChance) {
81:     const pointWinner = server;
82:     const speed = Math.round(180 + (servingPlayer.stats.serve - 50) * 1.1 + Math.random() * 15);
83:     return {
84:       winner: pointWinner,
85:       outcomeType: 'ace',
86:       rallyLength: 1,
