115:     const shots = ['мощный форхенд по линии', 'косой кросс с бэкхенда', 'точный укороченный под сетку', 'смэш у сетки'];
116:     const chosenShot = shots[Math.floor(Math.random() * shots.length)];
117:     desc = `Виннер! ${winnerPlayer.nameRu} пробивает ${chosenShot} (розыгрыш ${rallyLength} уд.)`;
118:   } else if (outcomeType === 'unforced_error') {
119:     const loser = pointWinner === 1 ? player2 : player1;
