134: export function repairTournamentBracket(tournament: Tournament, allPlayers: Player[]): Tournament {
135:   const updatedTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
136:   const eligiblePlayers = allPlayers
137:     .filter((p) => p.tour === updatedTournament.tour && !p.retired)
138:     .sort((a, b) => a.rank - b.rank);
139: 
140:   const numRounds = Math.log2(updatedTournament.drawSize);
141: 
142:   // Group matches by round
143:   const roundMatchesMap = new Map<number, Match[]>();
144:   for (let r = 0; r < numRounds; r++) {
145:     roundMatchesMap.set(r, updatedTournament.matches.filter((m) => m.round === r));
146:   }
147: 
148:   // 1. Ensure all nextMatchId / nextMatchSlot links are completely valid
149:   for (let round = 0; round < numRounds - 1; round++) {
150:     const currMatches = roundMatchesMap.get(round) || [];
151:     const nextMatches = roundMatchesMap.get(round + 1) || [];
152: 
153:     for (let i = 0; i < currMatches.length; i++) {
154:       const targetNextMatch = nextMatches[Math.floor(i / 2)];
155:       if (targetNextMatch) {
156:         currMatches[i].nextMatchId = targetNextMatch.id;
157:         currMatches[i].nextMatchSlot = (i % 2 === 0 ? 1 : 2);
158:       }
159:     }
160:   }
161: 
162:   // 2. Fix missing players in Round 0
163:   const r0Matches = roundMatchesMap.get(0) || [];
164:   const assignedPlayerIds = new Set<string>();
165:   r0Matches.forEach((m) => {
166:     if (m.player1Id) assignedPlayerIds.add(m.player1Id);
167:     if (m.player2Id) assignedPlayerIds.add(m.player2Id);
168:   });
169: 
170:   const unassignedPlayers = eligiblePlayers.filter((p) => !assignedPlayerIds.has(p.id));
171:   let unassignedIdx = 0;
172: 
173:   r0Matches.forEach((m) => {
174:     if (!m.player1Id && unassignedIdx < unassignedPlayers.length) {
175:       m.player1Id = unassignedPlayers[unassignedIdx++].id;
176:       const pObj = allPlayers.find((p) => p.id === m.player1Id);
177:       if (pObj && pObj.rank <= 32) m.seed1 = pObj.rank;
178:     }
179:     if (!m.player2Id && unassignedIdx < unassignedPlayers.length) {
180:       m.player2Id = unassignedPlayers[unassignedIdx++].id;
181:       const pObj = allPlayers.find((p) => p.id === m.player2Id);
182:       if (pObj && pObj.rank <= 32) m.seed2 = pObj.rank;
183:     }
184:   });
185: 
186:   // 3. Propagate completed match winners forward to next round matches
187:   for (let round = 0; round < numRounds - 1; round++) {
188:     const currMatches = roundMatchesMap.get(round) || [];
189:     for (const match of currMatches) {
190:       if (match.isCompleted && match.winnerId && match.nextMatchId) {
191:         const nextMatch = updatedTournament.matches.find((m) => m.id === match.nextMatchId);
192:         if (nextMatch) {
193:           if (match.nextMatchSlot === 1) {
194:             nextMatch.player1Id = match.winnerId;
195:             const pObj = allPlayers.find((p) => p.id === match.winnerId);
196:             if (pObj && pObj.rank <= 32) nextMatch.seed1 = pObj.rank;
197:           } else {
198:             nextMatch.player2Id = match.winnerId;
199:             const pObj = allPlayers.find((p) => p.id === match.winnerId);
200:             if (pObj && pObj.rank <= 32) nextMatch.seed2 = pObj.rank;
201:           }
202:         }
203:       }
204:     }
205:   }
206: 
207:   // 4. Check if final completed
208:   const finalMatch = updatedTournament.matches.find((m) => m.round === numRounds - 1);
209:   if (finalMatch && finalMatch.isCompleted && finalMatch.winnerId) {
210:     updatedTournament.isCompleted = true;
211:     updatedTournament.championId = finalMatch.winnerId;
212:     const loserId = finalMatch.player1Id === finalMatch.winnerId ? finalMatch.player2Id : finalMatch.player1Id;
213:     if (loserId) updatedTournament.runnerUpId = loserId;
214:   }
215: 
216:   return updatedTournament;
217: }
