105:   const serverWinProb = adjustedServerPower / (adjustedServerPower + adjustedReceiverPower);
106:   const serverWins = Math.random() < serverWinProb;
107:   const pointWinner: 1 | 2 = serverWins ? server : (server === 1 ? 2 : 1);
108:   const winnerPlayer = pointWinner === 1 ? player1 : player2;
