155: export function simulateFullMatch(
156:   player1: Player,
157:   player2: Player,
158:   surface: SurfaceType,
159:   setsToWin: 2 | 3 = 2
160: ): { score: MatchScore; winnerId: string } {
161:   const sets: Array<[number, number]> = [];
162:   const tiebreaks: Array<[number, number] | null> = [];
163: 
164:   let p1SetsWon = 0;
165:   let p2SetsWon = 0;
166: 
167:   const stats: MatchDetailedStats = {
168:     aces: [0, 0],
169:     doubleFaults: [0, 0],
170:     firstServePercentage: [62 + Math.floor(Math.random() * 12), 62 + Math.floor(Math.random() * 12)],
171:     firstServePointsWon: [0, 0],
172:     secondServePointsWon: [0, 0],
173:     breakPointsConverted: [0, 0],
174:     breakPointsTotal: [0, 0],
175:     winners: [0, 0],
176:     unforcedErrors: [0, 0],
177:     totalPointsWon: [0, 0],
178:     fastestServeKmH: [
179:       Math.round(200 + (player1.stats.serve - 70) * 0.8 + Math.random() * 10),
180:       Math.round(200 + (player2.stats.serve - 70) * 0.8 + Math.random() * 10),
181:     ],
182:   };
183: 
184:   let server: 1 | 2 = Math.random() > 0.5 ? 1 : 2;
185: 
186:   while (p1SetsWon < setsToWin && p2SetsWon < setsToWin) {
187:     let p1Games = 0;
188:     let p2Games = 0;
189: 
190:     while (true) {
191:       // Check set finish
192:       if (p1Games >= 6 && p1Games - p2Games >= 2) {
193:         sets.push([p1Games, p2Games]);
194:         tiebreaks.push(null);
195:         p1SetsWon++;
196:         break;
197:       }
198:       if (p2Games >= 6 && p2Games - p1Games >= 2) {
199:         sets.push([p1Games, p2Games]);
200:         tiebreaks.push(null);
201:         p2SetsWon++;
202:         break;
203:       }
204: 
205:       // Tiebreak at 6-6
206:       if (p1Games === 6 && p2Games === 6) {
207:         let p1Tb = 0;
208:         let p2Tb = 0;
209: 
210:         while ((p1Tb < 7 && p2Tb < 7) || Math.abs(p1Tb - p2Tb) < 2) {
211:           const pt = simulateSinglePoint(player1, player2, surface, server, true, p1Tb, p2Tb);
212:           if (pt.winner === 1) {
213:             p1Tb++;
214:             stats.totalPointsWon[0]++;
215:           } else {
216:             p2Tb++;
217:             stats.totalPointsWon[1]++;
218:           }
219:           if (pt.outcomeType === 'ace') stats.aces[pt.winner - 1]++;
220:           if (pt.outcomeType === 'double_fault') stats.doubleFaults[pt.winner === 1 ? 1 : 0]++;
221:           if (pt.outcomeType === 'winner') stats.winners[pt.winner - 1]++;
222:           if (pt.outcomeType === 'unforced_error') stats.unforcedErrors[pt.winner === 1 ? 1 : 0]++;
223: 
224:           if ((p1Tb + p2Tb) % 2 === 1) {
225:             server = server === 1 ? 2 : 1;
226:           }
227:         }
228: 
229:         if (p1Tb > p2Tb) {
230:           p1Games++;
231:           p1SetsWon++;
232:         } else {
233:           p2Games++;
234:           p2SetsWon++;
235:         }
236: 
237:         sets.push([p1Games, p2Games]);
238:         tiebreaks.push([p1Tb, p2Tb]);
239:         break;
240:       }
241: 
242:       // Regular Game simulation
243:       let p1Points = 0;
244:       let p2Points = 0;
245:       const initialServer = server;
246: 
247:       while (true) {
248:         const pt = simulateSinglePoint(player1, player2, surface, server, false, p1Points, p2Points);
249:         if (pt.winner === 1) {
250:           p1Points++;
251:           stats.totalPointsWon[0]++;
252:         } else {
253:           p2Points++;
254:           stats.totalPointsWon[1]++;
255:         }
256: 
257:         if (pt.outcomeType === 'ace') stats.aces[pt.winner - 1]++;
258:         if (pt.outcomeType === 'double_fault') stats.doubleFaults[pt.winner === 1 ? 1 : 0]++;
259:         if (pt.outcomeType === 'winner') stats.winners[pt.winner - 1]++;
260:         if (pt.outcomeType === 'unforced_error') stats.unforcedErrors[pt.winner === 1 ? 1 : 0]++;
261: 
262:         // Break point check
263:         if (server === 1 && p2Points >= 3 && p2Points > p1Points) {
264:           stats.breakPointsTotal[1]++;
265:         } else if (server === 2 && p1Points >= 3 && p1Points > p2Points) {
266:           stats.breakPointsTotal[0]++;
267:         }
268: 
269:         // Win Game check
270:         if (p1Points >= 4 && p1Points - p2Points >= 2) {
271:           p1Games++;
272:           if (initialServer === 2) stats.breakPointsConverted[0]++;
273:           break;
274:         }
275:         if (p2Points >= 4 && p2Points - p1Points >= 2) {
276:           p2Games++;
277:           if (initialServer === 1) stats.breakPointsConverted[1]++;
278:           break;
279:         }
280:       }
281: 
282:       server = server === 1 ? 2 : 1;
283:     }
284:   }
285: 
286:   const winnerId = p1SetsWon > p2SetsWon ? player1.id : player2.id;
287:   const durationMinutes = Math.round(45 * sets.length + Math.random() * 30);
288: 
289:   return {
290:     winnerId,
291:     score: {
292:       sets,
293:       tiebreaks,
294:       winnerId,
295:       durationMinutes,
296:       stats,
297:     },
298:   };
299: }

